package foxy

import (
	"fmt"
	"net/url"
	"strconv"
	"strings"
)

const (
	// RelayForwardedHeader is added by RxFoxyVPN Worker / PHP relays on forwarded responses.
	RelayForwardedHeader = "X-RxVpN-Relay"
	// RelayErrorHeader marks responses generated by the relay itself rather than upstream Mozilla.
	RelayErrorHeader = "X-Relay-Error"
	// RelayRecoveryHeader records which HTTP 451 / unreachable recovery step succeeded.
	RelayRecoveryHeader = "X-RxFoxy-Recovery"
	// RelayRecoveryExhaustedHeader records why HTTP 451 recovery could not recover the request.
	RelayRecoveryExhaustedHeader = "X-RxFoxy-Recovery-Exhausted"

	maxRelayURLLen = 2048
)

// RelayConfig mirrors Android's RelayConfig + manifest overrides for control-plane requests.
type RelayConfig struct {
	SharedEnabled            bool
	PersonalEnabled          bool
	PersonalURL              string
	PersonalOnly             bool
	SharedSecret             string
	ManifestPrimaryOverride  string
	ManifestFallbackOverride string
}

// RelayConfigSource supplies the current RelayConfig on each control-plane request.
type RelayConfigSource func() RelayConfig

// PersonalURLError classifies why a personal relay URL failed validation.
type PersonalURLError string

const (
	PersonalURLOK       PersonalURLError = ""
	PersonalURLNotHTTPS PersonalURLError = "not_https"
	PersonalURLNoSecret PersonalURLError = "no_secret"
	PersonalURLInvalid  PersonalURLError = "invalid"
)

// PersonalURLValidationError wraps a PersonalURLError as a Go error.
type PersonalURLValidationError struct {
	Kind PersonalURLError
}

func (e *PersonalURLValidationError) Error() string {
	switch e.Kind {
	case PersonalURLNotHTTPS:
		return "relay URL must start with https://"
	case PersonalURLNoSecret:
		return "relay URL must include ?secret=YOUR_SECRET"
	default:
		return "invalid relay URL"
	}
}

var relayAllowedDomains = []string{
	"mozilla.org",
	"mozilla.com",
	"firefox.com",
	"github.com",
	"githubusercontent.com",
	"jsdelivr.net",
}

func isEffectiveHTTPS443(u *url.URL) bool {
	if u == nil || !strings.EqualFold(u.Scheme, "https") {
		return false
	}
	p := u.Port()
	return p == "" || p == "443"
}

func hasValidOptionalPort(u *url.URL) bool {
	if u == nil {
		return false
	}
	p := u.Port()
	if p == "" {
		return true
	}
	n, err := strconv.Atoi(p)
	return err == nil && n >= 1 && n <= 65535
}

// IsRelayTargetAllowed matches RelayPolicy.isTargetAllowed in relay.zip:
// HTTPS on port 443, no userinfo, no fragment, and host equal to or a subdomain of ALLOWED_DOMAINS.
func IsRelayTargetAllowed(u *url.URL) bool {
	if !isEffectiveHTTPS443(u) {
		return false
	}
	if u.User != nil || u.Fragment != "" || u.RawFragment != "" {
		return false
	}
	host := strings.ToLower(strings.TrimSuffix(u.Hostname(), "."))
	if host == "" {
		return false
	}
	for _, domain := range relayAllowedDomains {
		if host == domain || strings.HasSuffix(host, "."+domain) {
			return true
		}
	}
	return false
}

// IsGuardianRequest reports whether u targets Mozilla's Guardian FPN API
// (https://vpn.mozilla.org/api/v1/fpn or /api/v1/fpn/...).
func IsGuardianRequest(u *url.URL) bool {
	if !isEffectiveHTTPS443(u) || u.User != nil {
		return false
	}
	if !strings.EqualFold(u.Hostname(), "vpn.mozilla.org") {
		return false
	}
	p := u.Path
	return p == "/api/v1/fpn" || strings.HasPrefix(p, "/api/v1/fpn/")
}

// DoubledLeadingSlash rewrites https://vpn.mozilla.org/api/... to https://vpn.mozilla.org//api/...
// while preserving query parameters. Returns nil if the path is empty, "/", or already "//...".
func DoubledLeadingSlash(u *url.URL) *url.URL {
	if u == nil {
		return nil
	}
	p := u.EscapedPath()
	if p == "" || p == "/" || strings.HasPrefix(p, "//") {
		return nil
	}
	clone := *u
	clone.Path = "/" + u.Path
	if u.RawPath != "" {
		clone.RawPath = "/" + u.RawPath
	} else {
		clone.RawPath = ""
	}
	return &clone
}

// ValidatePersonalRelayURL validates a user-entered personal relay URL against RelayPolicy.kt:
// non-blank, <=2048 chars, https scheme, non-empty host, valid port, no userinfo, no fragment,
// no url/health query parameters, and a non-blank secret query parameter.
func ValidatePersonalRelayURL(raw string) (*url.URL, error) {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" || len(trimmed) > maxRelayURLLen {
		return nil, &PersonalURLValidationError{Kind: PersonalURLInvalid}
	}
	if strings.Contains(trimmed, "#") {
		return nil, &PersonalURLValidationError{Kind: PersonalURLInvalid}
	}
	lower := strings.ToLower(trimmed)
	if !strings.HasPrefix(lower, "https://") {
		if strings.Contains(lower, "://") {
			return nil, &PersonalURLValidationError{Kind: PersonalURLNotHTTPS}
		}
		return nil, &PersonalURLValidationError{Kind: PersonalURLInvalid}
	}
	u, err := url.Parse(trimmed)
	if err != nil {
		return nil, &PersonalURLValidationError{Kind: PersonalURLInvalid}
	}
	if !strings.EqualFold(u.Scheme, "https") {
		return nil, &PersonalURLValidationError{Kind: PersonalURLNotHTTPS}
	}
	if u.Hostname() == "" || !hasValidOptionalPort(u) || u.User != nil || u.Fragment != "" {
		return nil, &PersonalURLValidationError{Kind: PersonalURLInvalid}
	}
	q, err := url.ParseQuery(u.RawQuery)
	if err != nil {
		return nil, &PersonalURLValidationError{Kind: PersonalURLInvalid}
	}
	hasSecret := false
	for k, vals := range q {
		switch strings.ToLower(k) {
		case "url", "health":
			return nil, &PersonalURLValidationError{Kind: PersonalURLInvalid}
		case "secret":
			for _, v := range vals {
				if strings.TrimSpace(v) != "" {
					hasSecret = true
				}
			}
		}
	}
	if !hasSecret {
		return nil, &PersonalURLValidationError{Kind: PersonalURLNoSecret}
	}
	if u.Path == "" {
		u.Path = "/"
	}
	u.Scheme = "https"
	u.Host = strings.ToLower(u.Host)
	return u, nil
}

// NormalizeSharedRelayCandidate validates a public manifest relay URL (SharedRelayManager.normalizeRelayCandidate):
// https, port 443, non-empty host, no userinfo, no fragment, no url/health query parameters, <=2048 chars.
func NormalizeSharedRelayCandidate(raw string) (string, bool) {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" || len(trimmed) > maxRelayURLLen || strings.Contains(trimmed, "#") {
		return "", false
	}
	u, err := url.Parse(trimmed)
	if err != nil || !isEffectiveHTTPS443(u) || u.Hostname() == "" || u.User != nil || u.Fragment != "" {
		return "", false
	}
	q, err := url.ParseQuery(u.RawQuery)
	if err != nil {
		return "", false
	}
	for k := range q {
		lk := strings.ToLower(k)
		if lk == "url" || lk == "health" {
			return "", false
		}
	}
	u.Scheme = "https"
	u.Host = strings.ToLower(u.Hostname())
	if u.Path == "" {
		u.Path = "/"
	}
	return u.String(), true
}

// AttachRelaySecret appends secret=<sharedSecret> to a relay candidate URL unless sharedSecret is empty
// or the candidate already carries a secret query parameter.
func AttachRelaySecret(candidateURL, sharedSecret string) string {
	secret := strings.TrimSpace(sharedSecret)
	if secret == "" {
		return candidateURL
	}
	u, err := url.Parse(candidateURL)
	if err != nil {
		return candidateURL
	}
	q := u.Query()
	for k := range q {
		if strings.EqualFold(k, "secret") {
			return candidateURL
		}
	}
	appendRawQueryParam(u, "secret", secret)
	return u.String()
}

// WithoutRelaySecret strips any secret query parameter from raw so sticky/cooldown maps
// never retain secrets or break when SharedSecret changes.
func WithoutRelaySecret(raw string) string {
	u, err := url.Parse(raw)
	if err != nil {
		return raw
	}
	if u.RawQuery == "" {
		return u.String()
	}
	parts := strings.Split(u.RawQuery, "&")
	kept := make([]string, 0, len(parts))
	for _, p := range parts {
		if p == "" {
			continue
		}
		name := p
		if i := strings.IndexByte(p, '='); i >= 0 {
			name = p[:i]
		}
		decoded, err := url.QueryUnescape(name)
		if err == nil {
			name = decoded
		}
		if strings.EqualFold(name, "secret") {
			continue
		}
		kept = append(kept, p)
	}
	u.RawQuery = strings.Join(kept, "&")
	return u.String()
}

// RedactRelayURL masks secret and url query parameters for safe logging.
func RedactRelayURL(raw string) string {
	u, err := url.Parse(strings.TrimSpace(raw))
	if err != nil || u.Host == "" {
		return "[invalid-relay-url]"
	}
	return fmt.Sprintf("%s://%s%s", u.Scheme, strings.ToLower(u.Host), u.Path)
}

func appendRawQueryParam(u *url.URL, key, value string) {
	encoded := url.QueryEscape(key) + "=" + url.QueryEscape(value)
	if u.RawQuery == "" {
		u.RawQuery = encoded
	} else {
		u.RawQuery = u.RawQuery + "&" + encoded
	}
}
